<?php
namespace Tests\Feature;
use App\Livewire\LMS\Quizzes\Index; use App\Models\{AcademicYear,ClassSubject,School,SchoolClass,Subject,Teacher,User}; use Illuminate\Foundation\Testing\RefreshDatabase; use Livewire\Livewire; use Spatie\Permission\Models\Role; use Tests\TestCase;
class QuizCrudTest extends TestCase { use RefreshDatabase; public function test_school_admin_can_create_a_quiz():void { Role::create(['name'=>'school_admin']);$user=User::factory()->create();$user->assignRole('school_admin');$school=School::create(['name'=>'BrightStar Academy','code'=>'BSA']);$year=AcademicYear::create(['school_id'=>$school->id,'name'=>'2026/2027','starts_at'=>'2026-09-01','ends_at'=>'2027-07-31']);$class=SchoolClass::create(['academic_year_id'=>$year->id,'name'=>'Basic 4']);$subject=Subject::create(['school_id'=>$school->id,'name'=>'Mathematics','code'=>'MATH']);$teacher=Teacher::create(['school_id'=>$school->id,'employee_id'=>'T-001','first_name'=>'Ama','last_name'=>'Mensah']);$classSubject=ClassSubject::create(['school_class_id'=>$class->id,'subject_id'=>$subject->id,'teacher_id'=>$teacher->id]);Livewire::actingAs($user)->test(Index::class)->call('create')->set('classSubjectId',(string)$classSubject->id)->set('title','Fractions Quiz')->set('maxAttempts','2')->set('status','published')->call('save')->assertHasNoErrors();$this->assertDatabaseHas('quizzes',['class_subject_id'=>$classSubject->id,'teacher_id'=>$teacher->id,'title'=>'Fractions Quiz','max_attempts'=>2]);} }
